def with_conditional_vars(args, acc, expr, stack, context, fun) do
  %{vars: vars, conditional_vars: conditional_vars} = context

  {vars_conds, {acc, context}} =
    Enum.map_reduce(args, {acc, context}, fn arg, {acc, context} ->
